{
  "title": "Assessing a Reportable Incident",
  "setting": "During military operations, within a DOD component and its chain of command",
  "decider": "The unit commander",
  "agent_recast": false,
  "recast_note": "",
  "agent": "The unit commander",
  "agent_role": "decide",
  "situation": "The unit commander has information about an allegation of a law-of-war violation. The commander must assess whether the information is credible and whether the allegation meets the threshold for a reportable incident. The assessment concerns whether the information is sufficiently accurate to warrant further review, not whether a violation has been established. The totality of the circumstances is relevant, including source reliability and any contradictory or corroborating information. A reporting determination must be handled through the chain of command.",
  "question": "What should the unit commander do with the allegation after assessing the available information?",
  "facts": [
    {
      "id": "F1",
      "kind": "authority",
      "status": "confirmed",
      "fact": "A reportable incident is one that a unit commander or other responsible official determines, based on credible information, potentially involves a war crime, another law-of-war violation, or conduct during military operations that would be a war crime in armed conflict.",
      "spans": [
        "src:25e83db5c245#p105.2"
      ]
    },
    {
      "id": "F2",
      "kind": "authority",
      "status": "confirmed",
      "fact": "The threshold is whether credible information merits further review; the commander need not determine that a potential violation occurred.",
      "spans": [
        "src:25e83db5c245#p105.2"
      ]
    },
    {
      "id": "F3",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Credible information is information a reasonable military commander would believe sufficiently accurate to warrant further review of an alleged violation.",
      "spans": [
        "src:25e83db5c245#p105.3"
      ]
    },
    {
      "id": "F4",
      "kind": "authority",
      "status": "confirmed",
      "fact": "The credibility assessment considers the totality of the circumstances, including the source’s reliability, how the source obtained the information, and whether contradictory or corroborating information exists.",
      "spans": [
        "src:25e83db5c245#p105.3"
      ]
    },
    {
      "id": "F5",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The unit commander has information about an alleged law-of-war violation and must assess whether it is based on credible information and constitutes a reportable incident.",
      "spans": [
        "src:25e83db5c245#p105.3"
      ]
    },
    {
      "id": "F6",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Military and U.S. civilian employees, contractor personnel, and subcontractors assigned to or accompanying a DOD component must report reportable incidents through their chain of command, including allegations involving non-DOD personnel.",
      "spans": [
        "src:25e83db5c245#p105.3"
      ]
    },
    {
      "id": "F7",
      "kind": "authority",
      "status": "confirmed",
      "fact": "A unit commander must immediately report a reportable incident through the chain of command to the combatant commander using operational incident reporting procedures or other expeditious means.",
      "spans": [
        "src:25e83db5c245#p105.3"
      ]
    },
    {
      "id": "F8",
      "kind": "authority",
      "status": "confirmed",
      "fact": "If the unit commander or a superior commander determines that an allegation is not supported by credible information, that determination is forwarded through the chain of command to the appropriate combatant commander.",
      "spans": [
        "src:25e83db5c245#p105.4"
      ]
    },
    {
      "id": "F9",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Military Department and Service regulations require concurrent reporting up the Service chain of command.",
      "spans": [
        "src:25e83db5c245#p105.4"
      ]
    }
  ],
  "options": {
    "O1": {
      "do": "The unit commander reports the allegation through the chain of command to the combatant commander using operational incident procedures or another expeditious means.",
      "move": "act",
      "disposition": "report",
      "irreversible": false
    },
    "O2": {
      "do": "The unit commander withholds a report of the allegation and forwards a determination of insufficient credible information through the chain to the combatant commander.",
      "move": "act",
      "disposition": "withhold",
      "irreversible": false
    }
  },
  "opposite_pair": [
    "O1",
    "O2"
  ],
  "real_option": "O1",
  "authored_options": [
    "O2"
  ],
  "no_opposite_reason": "",
  "basis_statement": "DODD 2311.01 reporting doctrine requires reporting when credible information warrants further review and provides for forwarding a determination when an allegation is not supported by credible information."
}
